        "#version 300 es\n#extension GL_OES_EGL_image_external_essl3 : require\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\nprecision mediump samplerExternalOES;\n\nin highp vec2 vTextureCoord;\nout vec4 fragColor;\n\nuniform sampler2D halationBlurTempTexture;\nuniform highp vec2 halationBlurResInv;\n\nuniform highp float redHalationOffset;\nuniform float halationBlurHueGreen;\nuniform float halationBlurHueBlue;\n\nfloat toLinear(float v) {\n  return pow(v, float(2.2));\n}\nvec3 toLinear(vec3 v) {\n  return pow(v, vec3(2.2));\n}\n\nvec3 toGamma(vec3 v) {\n  return pow(v, vec3(1.0 / 2.2));\n}\n\nvoid main() {\n    highp vec2 point0 = vTextureCoord + (vec2(redHalationOffset, redHalationOffset) * halationBlurResInv);\n    highp vec2 point1 = vTextureCoord + (vec2(redHalationOffset, -redHalationOffset) * halationBlurResInv);\n    highp vec2 point2 = vTextureCoord + (vec2(-redHalationOffset, redHalationOffset) * halationBlurResInv);\n    highp vec2 point3 = vTextureCoord + (vec2(-redHalationOffset, -redHalationOffset) * halationBlurResInv);\n\n\n    vec3 colorCenter = textureLod(halationBlurTempTexture, vTextureCoord, 0.0).rgb;\n    \n    vec3 color0 = toLinear(textureLod(halationBlurTempTexture, point0, 0.0).rgb);\n    vec3 color1 = toLinear(textureLod(halationBlurTempTexture, point1, 0.0).rgb);\n    vec3 color2 = toLinear(textureLod(halationBlurTempTexture, point2, 0.0).rgb);\n    vec3 color3 = toLinear(textureLod(halationBlurTempTexture, point3, 0.0).rgb);\n\n    vec3 resultColor = toGamma((color0 + color1 + color2 + color3) * 0.25);\n\n    fragColor = vec4(vec3(resultColor.r, mix(colorCenter.g, resultColor.g , halationBlurHueGreen) , mix(colorCenter.b, resultColor.b , halationBlurHueBlue) ), 1.0);\n}      ";
        f25835a = "#version 300 es\nprecision highp float;\nprecision highp int;\nlayout (location = 0)  in vec4 aPosition;\nlayout (location = 1)  in vec4 aTextureCoord;\nout highp vec2 vTextureCoord;\n\nvoid main() {  \n    gl_Position =  aPosition;    \n    vTextureCoord = aTextureCoord.xy;\n}";
        "#version 300 es\n#extension GL_OES_EGL_image_external_essl3 : require\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\nprecision mediump samplerExternalOES;\n\nin highp vec2 vTextureCoord;\nout vec4 fragColor;\n\nuniform sampler2D halationHighSourceTexture;\nuniform float halationIntensity;\nuniform float halationCuttoff;\n\nfloat luma(vec3 color) {\n  return dot(color, vec3(0.299, 0.587, 0.114));\n}\n\nvec3 toLinear(vec3 v) {\n  return pow(v, vec3(2.2));\n}\n\nvec3 applyIntensity(vec3 v) {\n  return  (smoothstep(halationCuttoff/*0.35*/, 1.0, v)) * halationIntensity;\n}\n\nvec3 toGamma(vec3 v) {\n  return pow(v, vec3(1.0 / 2.2));\n}\n\n\nvoid main() { \n  vec4 src = textureLod(halationHighSourceTexture, vTextureCoord, 0.0);   \n  vec3 srcLinear =  toGamma(applyIntensity(toLinear(src.rgb)));  \n  fragColor = vec4(srcLinear, 1.0);\n}      ";
        "#version 300 es\n#extension GL_OES_EGL_image_external_essl3 : require\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\nprecision mediump samplerExternalOES;\n\nin highp vec2 vTextureCoord;\nout vec4 fragColor;\n\nuniform sampler2D textureHalationMergeSource;\nuniform sampler2D textureHalationMergeBlur;\nuniform float halationMergeIntensity;\nuniform float halationMergeHueGreen;\nuniform float halationMergeHueBlue;\n\nvec3 toLinear(vec3 v) {\n  return pow(v, vec3(2.2));\n}\n\nvec3 toGamma(vec3 v) {\n  return pow(v, vec3(1.0 / 2.2));\n}\n\n\nvoid main() { \n    vec4 colorIn;\n    colorIn = textureLod(textureHalationMergeSource, vTextureCoord, 0.0);\n    vec4 halColorIn;\n    halColorIn = textureLod(textureHalationMergeBlur, vTextureCoord, 0.0);\n    \n    vec3 mergedColor = toGamma(toLinear(colorIn.rgb) + toLinear(vec3(halColorIn.r, halColorIn.g * halationMergeHueGreen, halColorIn.b * halationMergeHueBlue)) * 15.0 * halationMergeIntensity );\n    fragColor =  vec4(clamp(mergedColor, 0.0, 1.0), 1.0);\n}      ";
