        f25841g = "#version 300 es\nprecision highp float;\nprecision highp int;\nprecision highp sampler3D;\nprecision highp isampler2D;\nprecision highp sampler2D;\n\nin highp vec2 vTextureCoord;\nout vec4 fragColor;\nuniform isampler2D histSumTexture;\nuniform highp int clampedHeight;\n\nvoid main() {   \n    mediump ivec3 amp;\n \n    amp.r = texelFetch(histSumTexture, ivec2(vTextureCoord.x * 255.0 + 0.5, 0), 0).r;\n    amp.g = texelFetch(histSumTexture, ivec2(vTextureCoord.x * 255.0 + 0.5, 1), 0).r;\n    amp.b = texelFetch(histSumTexture, ivec2(vTextureCoord.x * 255.0 + 0.5, 2), 0).r;\n    \n    \n    //highp vec3 color = (vec3(1.0) - step(vec3(amp),  vec3(clampedHeight * vTextureCoord.y))); \n    bvec3 pixelTest = greaterThan(amp, ivec3( float(clampedHeight) * vTextureCoord.y));\n    //fragColor =  vec4(clamp(color, 0.129411, 0.43921), 1.0);    \n    fragColor =  vec4(mix( vec3(0.129411), vec3(0.43921), vec3(pixelTest)), 1.0);    \n}      ";
        "#version 320 es\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\n\nlayout(binding = 5, rgba8) writeonly uniform highp image2D waveFormImageToClearR;\nlayout(binding = 6, rgba8) writeonly uniform highp image2D waveFormImageToClearG;\nlayout(binding = 7, rgba8) writeonly uniform highp image2D waveFormImageToClearB;\nlayout(local_size_x = 00000, local_size_y = 00000, local_size_z = 1) in;\n\nconst highp vec4 waveformClearColor = vec4(0.129411, 0.129411, 0.129411, 1.0);\n\nvoid main() {    \n    ivec2 storePos = ivec2(gl_GlobalInvocationID.xy);\n    imageStore(waveFormImageToClearR, storePos, waveformClearColor);        \n    imageStore(waveFormImageToClearG, storePos, waveformClearColor);        \n    imageStore(waveFormImageToClearB, storePos, waveformClearColor);        \n}      ";
        "#version 320 es\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\n\n\nuniform sampler2D waveformSourceTexture;\nuniform highp float waveformInvWidth;\nuniform highp float waveformInvHeight;\nlayout(binding = 5, rgba8) writeonly uniform highp image2D waveformOutputImageR;\nlayout(binding = 6, rgba8) writeonly uniform highp image2D waveformOutputImageG;\nlayout(binding = 7, rgba8) writeonly uniform highp image2D waveformOutputImageB;\nlayout(local_size_x = 00000, local_size_y = 00000, local_size_z = 1) in;\n\n\nvoid main() {    \n    // Read current global position for this thread\n    ivec2 storePos = ivec2(gl_GlobalInvocationID.xy);\n    int x = storePos.x;\n    int y = storePos.y;     \n\n    vec2 colorPosition = vec2(float(x) * waveformInvWidth, float(y) * waveformInvHeight);\n    ivec3 color = ivec3(textureLod(waveformSourceTexture, colorPosition, 0.0 ).rgb * vec3(255.0) + 0.5);\n    \n    vec2 colorPosition2 = vec2((float(x) + 0.5) * waveformInvWidth, float(y) * waveformInvHeight);\n    ivec3 color2 = ivec3(textureLod(waveformSourceTexture, colorPosition2, 0.0 ).rgb * vec3(255.0) + 0.5);\n\n    int yR = 511 - (color.r + color2.r);\n    int yG = 511 - (color.g + color2.g);\n    int yB = 511 - (color.b + color2.b);\n    imageStore(waveformOutputImageR, ivec2(x, yR), vec4(0.43921));        \n    imageStore(waveformOutputImageG, ivec2(x, yG), vec4(0.43921));        \n    imageStore(waveformOutputImageB, ivec2(x, yB), vec4(0.43921));        \n}      ";
        "#version 320 es\nprecision mediump float;\nprecision mediump int;\nprecision mediump sampler3D;\nprecision mediump sampler2D;\n\n\nuniform sampler2D waveformSourceTexture;\nuniform highp float waveformPortraitInvWidth;\nuniform highp float waveformPortraitInvHeight;\nlayout(binding = 5, rgba8) writeonly uniform highp image2D waveformOutputImageR;\nlayout(binding = 6, rgba8) writeonly uniform highp image2D waveformOutputImageG;\nlayout(binding = 7, rgba8) writeonly uniform highp image2D waveformOutputImageB;\nlayout(local_size_x = 00000, local_size_y = 00000, local_size_z = 1) in;\n\n\nvoid main() {    \n    // Read current global position for this thread\n    ivec2 storePos = ivec2(gl_GlobalInvocationID.xy);\n    int x = storePos.x;\n    int y = storePos.y;     \n    \n    vec2 colorPosition = vec2(2.0 * (float(y)) * waveformPortraitInvWidth, (float(x)) * waveformPortraitInvHeight);\n    ivec3 color = ivec3(textureLod(waveformSourceTexture, colorPosition, 0.0 ).rgb * vec3(255.0) + 0.5);\n    \n    vec2 colorPosition2 = vec2(2.0 * (float(y)) * waveformPortraitInvWidth, (float(x) + 0.5) * waveformPortraitInvHeight);\n    ivec3 color2 = ivec3(textureLod(waveformSourceTexture, colorPosition2, 0.0 ).rgb * vec3(255.0) + 0.5);\n\n    int yR = 511 - (color.r + color2.r);\n    int yG = 511 - (color.g + color2.g);\n    int yB = 511 - (color.b + color2.b);\n    imageStore(waveformOutputImageR, ivec2(x, yR), vec4(0.43921));        \n    imageStore(waveformOutputImageG, ivec2(x, yG), vec4(0.43921));        \n    imageStore(waveformOutputImageB, ivec2(x, yB), vec4(0.43921));        \n}      ";
